INSERT INTO icono_audit_age_years(bucket,total) SELECT strftime('%Y',datetime(OLD.last_audited_at)),-1  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL
      ON CONFLICT(bucket) DO UPDATE SET total=total-1;
      DELETE FROM icono_audit_age_years WHERE bucket=(SELECT strftime('%Y',datetime(OLD.last_audited_at))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL) AND total=0;
INSERT INTO icono_audit_age_months(bucket,total) SELECT strftime('%Y-%m',datetime(OLD.last_audited_at)),-1  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL
      ON CONFLICT(bucket) DO UPDATE SET total=total-1;
      DELETE FROM icono_audit_age_months WHERE bucket=(SELECT strftime('%Y-%m',datetime(OLD.last_audited_at))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL) AND total=0;
INSERT INTO icono_audit_age_days(bucket,total,seconds_json) SELECT date(datetime(OLD.last_audited_at)),-1,json_object(CAST((CAST(strftime('%H',datetime(OLD.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(OLD.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(OLD.last_audited_at)) AS INTEGER)) AS TEXT),-1)  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL
    ON CONFLICT(bucket) DO UPDATE SET total=total-1,seconds_json=json_set(seconds_json,(SELECT '$.'||(CAST(strftime('%H',datetime(OLD.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(OLD.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(OLD.last_audited_at)) AS INTEGER))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL),COALESCE(json_extract(seconds_json,(SELECT '$.'||(CAST(strftime('%H',datetime(OLD.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(OLD.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(OLD.last_audited_at)) AS INTEGER))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL)),0)-1);
    DELETE FROM icono_audit_age_days WHERE bucket=(SELECT date(datetime(OLD.last_audited_at))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol AND pa.asset_sha256=OLD.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND OLD.audit_state<>'unknown' AND datetime(OLD.last_audited_at) IS NOT NULL) AND total=0;
UPDATE icono_asset_summary_counts SET (audited_assets,verified_renderable_images,storage_incomplete_assets,storage_regionally_divergent_assets,broken_live_images,renderable_live_confirmed,storage_queue_backlog_assets)=(SELECT audited_assets+COALESCE(SUM(CASE WHEN NEW.audit_state<>'unknown' THEN 1 ELSE 0 END),0),verified_renderable_images+COALESCE(SUM(CASE WHEN NEW.audit_state IN ('renderable','regionally_divergent') THEN 1 ELSE 0 END),0),storage_incomplete_assets+COALESCE(SUM(CASE WHEN NEW.audit_state='broken' THEN 1 ELSE 0 END),0),storage_regionally_divergent_assets+COALESCE(SUM(CASE WHEN NEW.audit_state='regionally_divergent' THEN 1 ELSE 0 END),0),broken_live_images+COALESCE(SUM(CASE WHEN NEW.is_current=1 AND NEW.audit_state='broken' THEN 1 ELSE 0 END),0),renderable_live_confirmed+COALESCE(SUM(CASE WHEN NEW.is_current=1 AND NEW.audit_state IN ('renderable','regionally_divergent') THEN 1 ELSE 0 END),0),storage_queue_backlog_assets+COALESCE(SUM(CASE WHEN NEW.audit_state='unknown' THEN 1 ELSE 0 END),0)  WHERE EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) WHERE summary_key='default';
INSERT INTO icono_audit_age_years(bucket,total) SELECT strftime('%Y',datetime(NEW.last_audited_at)),+1  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL
      ON CONFLICT(bucket) DO UPDATE SET total=total+1;
