INSERT INTO icono_audit_age_months(bucket,total) SELECT strftime('%Y-%m',datetime(NEW.last_audited_at)),+1  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL
      ON CONFLICT(bucket) DO UPDATE SET total=total+1;
      DELETE FROM icono_audit_age_months WHERE bucket=(SELECT strftime('%Y-%m',datetime(NEW.last_audited_at))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL) AND total=0;
INSERT INTO icono_audit_age_days(bucket,total,seconds_json) SELECT date(datetime(NEW.last_audited_at)),+1,json_object(CAST((CAST(strftime('%H',datetime(NEW.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(NEW.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(NEW.last_audited_at)) AS INTEGER)) AS TEXT),+1)  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL
    ON CONFLICT(bucket) DO UPDATE SET total=total+1,seconds_json=json_set(seconds_json,(SELECT '$.'||(CAST(strftime('%H',datetime(NEW.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(NEW.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(NEW.last_audited_at)) AS INTEGER))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL),COALESCE(json_extract(seconds_json,(SELECT '$.'||(CAST(strftime('%H',datetime(NEW.last_audited_at)) AS INTEGER)*3600+CAST(strftime('%M',datetime(NEW.last_audited_at)) AS INTEGER)*60+CAST(strftime('%S',datetime(NEW.last_audited_at)) AS INTEGER))  WHERE (EXISTS(SELECT 1 FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol AND pa.asset_sha256=NEW.asset_sha256 AND COALESCE(pa.asset_sha256,'')<>'' AND COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected')) AND NEW.audit_state<>'unknown' AND datetime(NEW.last_audited_at) IS NOT NULL)),0)+1);
