END;

CREATE TRIGGER trg_icono_asset_summary_publish_insert AFTER INSERT ON icono_publish_state
BEGIN
UPDATE icono_asset_summary_counts SET (published_live_portraits,catalog_published_live_portraits)=(SELECT published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(NEW.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0),catalog_published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(NEW.current_asset_sha256,'')<>'' AND EXISTS(SELECT 1 FROM icono_gene_catalog gc WHERE gc.gene_symbol=NEW.gene_symbol) THEN 1 ELSE 0 END),0)  WHERE 1) WHERE summary_key='default';
END;

CREATE TRIGGER trg_icono_asset_summary_publish_delete AFTER DELETE ON icono_publish_state
BEGIN
UPDATE icono_asset_summary_counts SET (published_live_portraits,catalog_published_live_portraits)=(SELECT published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(OLD.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0),catalog_published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(OLD.current_asset_sha256,'')<>'' AND EXISTS(SELECT 1 FROM icono_gene_catalog gc WHERE gc.gene_symbol=OLD.gene_symbol) THEN 1 ELSE 0 END),0)  WHERE 1) WHERE summary_key='default';
END;

CREATE TRIGGER trg_icono_asset_summary_publish_update AFTER UPDATE OF gene_symbol,current_asset_sha256 ON icono_publish_state
WHEN OLD.gene_symbol IS NOT NEW.gene_symbol OR OLD.current_asset_sha256 IS NOT NEW.current_asset_sha256
BEGIN
UPDATE icono_asset_summary_counts SET (published_live_portraits,catalog_published_live_portraits)=(SELECT published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(OLD.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0),catalog_published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(OLD.current_asset_sha256,'')<>'' AND EXISTS(SELECT 1 FROM icono_gene_catalog gc WHERE gc.gene_symbol=OLD.gene_symbol) THEN 1 ELSE 0 END),0)  WHERE 1) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (published_live_portraits,catalog_published_live_portraits)=(SELECT published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(NEW.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0),catalog_published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(NEW.current_asset_sha256,'')<>'' AND EXISTS(SELECT 1 FROM icono_gene_catalog gc WHERE gc.gene_symbol=NEW.gene_symbol) THEN 1 ELSE 0 END),0)  WHERE 1) WHERE summary_key='default';
END;

CREATE TRIGGER trg_icono_asset_summary_catalog_insert AFTER INSERT ON icono_gene_catalog
BEGIN
UPDATE icono_asset_summary_counts SET (catalog_candidate_assets,catalog_auditable_assets)=(SELECT catalog_candidate_assets+COALESCE(SUM(CASE WHEN 1 THEN 1 ELSE 0 END),0),catalog_auditable_assets+COALESCE(SUM(CASE WHEN COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected' THEN 1 ELSE 0 END),0) FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (catalog_published_live_portraits)=(SELECT catalog_published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(ps.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0) FROM icono_publish_state ps WHERE ps.gene_symbol=NEW.gene_symbol) WHERE summary_key='default';
END;

CREATE TRIGGER trg_icono_asset_summary_catalog_delete AFTER DELETE ON icono_gene_catalog
BEGIN
UPDATE icono_asset_summary_counts SET (catalog_candidate_assets,catalog_auditable_assets)=(SELECT catalog_candidate_assets-COALESCE(SUM(CASE WHEN 1 THEN 1 ELSE 0 END),0),catalog_auditable_assets-COALESCE(SUM(CASE WHEN COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected' THEN 1 ELSE 0 END),0) FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (catalog_published_live_portraits)=(SELECT catalog_published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(ps.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0) FROM icono_publish_state ps WHERE ps.gene_symbol=OLD.gene_symbol) WHERE summary_key='default';
END;

CREATE TRIGGER trg_icono_asset_summary_catalog_update AFTER UPDATE OF gene_symbol ON icono_gene_catalog
WHEN OLD.gene_symbol IS NOT NEW.gene_symbol
BEGIN
UPDATE icono_asset_summary_counts SET (catalog_candidate_assets,catalog_auditable_assets)=(SELECT catalog_candidate_assets-COALESCE(SUM(CASE WHEN 1 THEN 1 ELSE 0 END),0),catalog_auditable_assets-COALESCE(SUM(CASE WHEN COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected' THEN 1 ELSE 0 END),0) FROM icono_portrait_assets pa WHERE pa.gene_symbol=OLD.gene_symbol) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (catalog_published_live_portraits)=(SELECT catalog_published_live_portraits-COALESCE(SUM(CASE WHEN COALESCE(ps.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0) FROM icono_publish_state ps WHERE ps.gene_symbol=OLD.gene_symbol) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (catalog_candidate_assets,catalog_auditable_assets)=(SELECT catalog_candidate_assets+COALESCE(SUM(CASE WHEN 1 THEN 1 ELSE 0 END),0),catalog_auditable_assets+COALESCE(SUM(CASE WHEN COALESCE(pa.is_legacy,0)=0 AND lower(COALESCE(pa.status,'draft'))<>'rejected' THEN 1 ELSE 0 END),0) FROM icono_portrait_assets pa WHERE pa.gene_symbol=NEW.gene_symbol) WHERE summary_key='default';
UPDATE icono_asset_summary_counts SET (catalog_published_live_portraits)=(SELECT catalog_published_live_portraits+COALESCE(SUM(CASE WHEN COALESCE(ps.current_asset_sha256,'')<>'' THEN 1 ELSE 0 END),0) FROM icono_publish_state ps WHERE ps.gene_symbol=NEW.gene_symbol) WHERE summary_key='default';
END;
